import{_ as o,o as p,c as l,ai as r}from"./chunks/framework.COht06hG.js";const P=JSON.parse('{"title":"Agent Skills、Rules、Prompt、MCP，一文把它们理清楚了","description":"","frontmatter":{},"headers":[],"relativePath":"ai/ai.md","filePath":"ai/ai.md"}'),i={name:"ai/ai.md"};function s(n,t,u,a,g,e){return p(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="agent-skills、rules、prompt、mcp-一文把它们理清楚了" tabindex="-1">Agent Skills、Rules、Prompt、MCP，一文把它们理清楚了 <a class="header-anchor" href="#agent-skills、rules、prompt、mcp-一文把它们理清楚了" aria-label="Permalink to “Agent Skills、Rules、Prompt、MCP，一文把它们理清楚了”">​</a></h1><blockquote><p>&quot;Agent Skills、Rules、Prompt、MCP到底有什么区别？我也想用AI，但每次看到这些词就头大。&quot;</p></blockquote><p>说实话，我理解这种困惑。</p><p>这就好比你去一家餐厅，菜单上写着&quot;前菜&quot;、&quot;主菜&quot;、&quot;配菜&quot;、&quot;佐料&quot;，但没人告诉你它们到底是什么关系。</p><p>今天，我们就把这些概念彻底掰开揉碎了讲清楚。</p><h3 id="_01" tabindex="-1">01 <a class="header-anchor" href="#_01" aria-label="Permalink to “01”">​</a></h3><p>一个真实的AI困惑</p><p>上周有个程序员朋友跟我说：</p><p>&quot;我写了一个Prompt，让AI帮我写代码，但它总理解不对我的需求。后来听说要加Rules，然后又有人说要用Skills，现在又冒出个MCP……我到底该用哪个？&quot;</p><p>这不是某个人的困惑，而是很多AI使用者的普遍困境。</p><p>因为AI生态发展太快，新概念层出不穷，但这些概念之间往往有重叠，边界不清。</p><p>更让人头大的是，不同的平台、不同的文档，对同一个词的叫法还不一样。</p><p><strong>但这四个概念，确实有本质的区别。</strong></p><h3 id="_02" tabindex="-1">02 <a class="header-anchor" href="#_02" aria-label="Permalink to “02”">​</a></h3><p>Prompt：你和AI的对话基础</p><p>先说最基础的：Prompt。</p><p>Prompt就是你给AI的输入，是你和AI对话的基础。</p><p>它可以是一句话、一段文字、一个问题、一个任务描述。</p><blockquote><p><strong>Prompt = 你对AI说的话</strong></p></blockquote><p>比如：</p><ul><li><p>&quot;帮我写一篇关于春天的诗&quot;</p></li><li><p>&quot;这段代码有什么bug？&quot;</p></li><li><p>&quot;解释一下量子纠缠&quot;</p></li></ul><p><strong>Prompt的特点</strong> ：</p><ul><li><p>简单直接，就像你在跟人聊天</p></li><li><p>每次对话都可以不同</p></li><li><p>适合一次性任务</p></li></ul><p><strong>Prompt的问题</strong> ：</p><ul><li><p>如果你经常要做类似的事情，每次都要重新输入Prompt</p></li><li><p>AI可能会&quot;忘记&quot;你之前的设置</p></li><li><p>无法复用和共享</p></li></ul><h3 id="_03" tabindex="-1">03 <a class="header-anchor" href="#_03" aria-label="Permalink to “03”">​</a></h3><p>Rules：给AI的&quot;行为准则&quot;</p><p>当你发现需要反复告诉AI同样的事情时，就需要Rules了。</p><p>Rules就是你给AI设定的长期规则，就像你给助理制定的&quot;工作手册&quot;。</p><blockquote><p><strong>Rules = AI的行为准则</strong></p></blockquote><p>比如：</p><ul><li><p>&quot;你是一个专业的程序员，写代码时要遵循PEP8规范&quot;</p></li><li><p>&quot;回复时要简短精炼，不要超过100字&quot;</p></li><li><p>&quot;遇到不确定的信息，要明确告诉用户&quot;</p></li></ul><p><strong>Rules的特点</strong> ：</p><ul><li><p>一次设置，长期生效</p></li><li><p>定义了AI的&quot;人设&quot;和&quot;行为模式&quot;</p></li><li><p>适合长期稳定的需求</p></li></ul><p><strong>Rules的问题</strong> ：</p><ul><li><p>只能定义&quot;做什么&quot;和&quot;不做什么&quot;，无法定义&quot;怎么做&quot;</p></li><li><p>无法包含复杂的操作步骤</p></li><li><p>仍然比较抽象</p></li></ul><h3 id="_04" tabindex="-1">04 <a class="header-anchor" href="#_04" aria-label="Permalink to “04”">​</a></h3><p>Skills：AI的&quot;超能力模板&quot;</p><p>现在进入重头戏：Skills。</p><p>Skills是AI的&quot;超能力模板&quot;，是一套完整的、可复用的、能解决特定问题的方案。</p><blockquote><p><strong>Skills = AI的超能力模板</strong></p></blockquote><p>一个Skill通常包含：</p><ul><li><p><strong>Prompt模板</strong> ：定义任务目标</p></li><li><p><strong>Rules</strong> ：设定行为规范</p></li><li><p><strong>操作步骤</strong> ：具体的执行流程</p></li><li><p><strong>工具调用</strong> ：需要用到的外部工具或API</p></li><li><p><strong>输出格式</strong> ：标准化的结果呈现</p></li></ul><p><strong>举个例子</strong> ：</p><p>假设你经常需要从网页抓取数据并生成报告。</p><ul><li><p><strong>用Prompt</strong> ：每次都要输入&quot;帮我访问这个网页，提取XX数据，然后生成报告&quot;</p></li><li><p><strong>用Rules</strong> ：可以设定&quot;你是个数据分析师，生成报告时要包含XX部分&quot;</p></li><li><p><strong>用Skill</strong> ：直接调用&quot;网页数据抓取Skill&quot;，它会自动完成访问→提取→分析→生成报告的全流程</p></li></ul><p><strong>Skills的特点</strong> ：</p><ul><li><p><strong>完整性</strong> ：从输入到输出的完整方案</p></li><li><p><strong>可复用</strong> ：一次创建，多次使用</p></li><li><p><strong>可共享</strong> ：可以被其他用户或Agent调用</p></li><li><p><strong>可组合</strong> ：多个Skill可以组合完成复杂任务</p></li></ul><p><strong>Skills的价值</strong> ：</p><ul><li><p>不用每次都重新描述需求</p></li><li><p>保证了输出的质量和一致性</p></li><li><p>可以在社区中共享和交换</p></li><li><p>让AI真正成为你的&quot;数字员工&quot;</p></li></ul><h3 id="_05" tabindex="-1">05 <a class="header-anchor" href="#_05" aria-label="Permalink to “05”">​</a></h3><p>MCP：连接AI和世界的&quot;桥梁&quot;</p><p>最后说MCP。</p><p>MCP（ModelContextProtocol）是一个技术协议，它的作用是让AI能够安全、规范地访问外部数据和服务。</p><blockquote><p><strong>MCP = AI和世界连接的协议</strong></p></blockquote><p>你可以把MCP理解成一套&quot;插座标准&quot;。</p><ul><li><p><strong>AI</strong> 是电器</p></li><li><p><strong>外部系统</strong> （数据库、API、文件系统）是电源</p></li><li><p><strong>MCP</strong> 是插座标准、</p></li></ul><p>有了统一的插座标准，电器就可以方便地连接各种电源，而不用担心接口不匹配。</p><p><strong>MCP解决的问题</strong> ：</p><ul><li><p><strong>安全问题</strong> ：如何让AI安全地访问敏感数据</p></li><li><p><strong>标准化问题</strong> ：不同的系统用统一的方式连接</p></li><li><p><strong>权限管理</strong> ：AI能做什么、不能做什么</p></li><li><p><strong>数据隔离</strong> ：避免AI越界访问不该访问的内容</p></li></ul><p><strong>MCP与Skills的关系</strong> ：</p><p>Skills是&quot;做什么&quot;，MCP是&quot;怎么安全地做&quot;。</p><p>一个Skill在执行过程中，如果需要访问外部系统，就会通过MCP协议来连接。</p><p>一张图看懂它们的关系</p><ul><li><p><strong>Prompt</strong> ：是你和AI对话的起点</p></li><li><p><strong>Rules</strong> ：定义AI的基本行为规范</p></li><li><p><strong>Skills</strong> ：封装了完整的任务解决方案</p></li><li><p><strong>MCP</strong> ：让AI能够安全地连接外部世界</p></li></ul><h3 id="_07" tabindex="-1">07 <a class="header-anchor" href="#_07" aria-label="Permalink to “07”">​</a></h3><p>实际场景中该用哪个？</p><p><strong>场景1：偶尔让AI帮个小忙</strong> → 用 <strong>Prompt</strong> 就够了</p><p>比如：&quot;帮我写个生日祝福语&quot;</p><p><strong>场景2：AI要长期扮演某个角色</strong> → 用 <strong>Rules</strong></p><p>比如：设定AI是&quot;你的私人英语老师&quot;，回复时要用简单英语，不超过50个单词</p><p><strong>场景3：经常要做一件复杂的事</strong> → 用 <strong>Skills</strong></p><p>比如：每周都要分析行业新闻并生成报告，那就创建一个&quot;行业报告生成Skill&quot;</p><p><strong>场景4：要让AI访问你的私有数据或API</strong> → 需要配置 <strong>MCP</strong></p><p>比如：让AI能够查询你的数据库、调用你的业务API</p><h3 id="_08" tabindex="-1">08 <a class="header-anchor" href="#_08" aria-label="Permalink to “08”">​</a></h3><p>为什么Skills这么重要？</p><p>你可能发现，这四个概念里，Skills是最&quot;重&quot;的。</p><p>它需要你花时间去设计、去调试、去优化。</p><p><strong>但为什么还要用Skills？</strong></p><p>因为当你用AI不再是为了&quot;偶尔玩玩&quot;，而是为了真正提升工作效率、解决实际问题时，你会发现：</p><ul><li><p><strong>时间成本</strong> ：一次创建，长期受益</p></li><li><p><strong>质量保证</strong> ：每次输出都稳定可靠</p></li><li><p><strong>团队协作</strong> ：可以分享给同事使用</p></li><li><p><strong>持续优化</strong> ：可以不断改进和完善</p></li></ul><p>更重要的是，Skills让AI从&quot;聊天工具&quot;变成了&quot;生产力工具&quot;。</p><h3 id="_09" tabindex="-1">09 <a class="header-anchor" href="#_09" aria-label="Permalink to “09”">​</a></h3><p>最后的建议</p><p>如果你刚开始用AI：</p><ol><li><p><strong>从Prompt开始</strong> ：先学会和AI对话，了解它的能力边界</p></li><li><p><strong>积累常用Prompt</strong> ：把经常用到的Prompt保存起来，形成&quot;个人Prompt库&quot;</p></li><li><p><strong>尝试Rules</strong> ：当发现需要反复设定同样规则时，开始用Rules</p></li><li><p><strong>创建Skills</strong> ：当有明确、重复的复杂任务时，尝试创建第一个Skill</p></li><li><p><strong>了解MCP</strong> ：如果需要让AI访问你的系统，再深入学习MCP</p></li></ol><p><strong>别被概念吓到。</strong></p><p>它们本质上都是为了让你更好地使用AI，从&quot;偶尔问一问&quot;进化到&quot;把它当成真正的数字助手&quot;。</p>',89)])])}const A=o(i,[["render",s]]);export{P as __pageData,A as default};
